            if (arrUsuariosActivar[i].data.activo == true) {
                mostrarMensaje(8, etiquetas.lbMsgYaActivados);
                arrUsuarioAct = [];
                return;
            }
            else
                arrUsuarioAct.push(arrUsuariosActivar[i].data.idusuario);
